{"name": "fws-Admins to jump hosts _app-rdp-gw_", "description": "", "enabled": true, "action": "ALLOW", "source": {"site": [{"by": "NAME", "input": "client"}]}, "destination": {"ip": ["203.0.113.40"]}, "service": {"custom": [{"protocol": "TCP_UDP", "port": [3389]}]}, "tracking": {"event": {"enabled": true}}, "exceptions": [{"source": {"ipRange": [{"from": "0.0.0.0", "to": "10.98.255.255"}, {"from": "10.99.1.0", "to": "255.255.255.255"}]}, "name": "fwshift 1"}]}
