{"name": "fws-Engineering to git", "description": "", "enabled": false, "action": "ALLOW", "source": {"site": [{"by": "NAME", "input": "client"}]}, "destination": {}, "service": {"custom": [{"protocol": "TCP", "port": [22, 9418]}]}, "tracking": {"event": {"enabled": true}}, "exceptions": []}
