cat > "$OUT/internet-016.json" <<'FWSHIFT_EOF'
{"name": "fws-block the rest to the internet", "description": "the source blocks what no rule matches; switch on after review", "enabled": false, "action": "BLOCK", "source": {}, "destination": {}, "service": {"custom": []}, "tracking": {"event": {"enabled": false}}, "exceptions": []}
